CREATE TABLE projects(id BLOB PRIMARY KEY,archived INTEGER,remote_project_id BLOB); CREATE TABLE tasks(id BLOB PRIMARY KEY,project_id BLOB,title TEXT,description TEXT,status TEXT); CREATE TABLE workspaces(id BLOB PRIMARY KEY,task_id BLOB,branch TEXT,name TEXT,archived INTEGER DEFAULT 0,worktree_deleted INTEGER DEFAULT 0,updated_at TEXT); CREATE TABLE sessions(id BLOB PRIMARY KEY,workspace_id BLOB,executor TEXT,agent_working_dir TEXT); CREATE TABLE repos(id BLOB PRIMARY KEY,name TEXT,default_working_dir TEXT); CREATE TABLE project_repos(project_id BLOB,repo_id BLOB); CREATE TABLE workspace_repos(id BLOB PRIMARY KEY,workspace_id BLOB,repo_id BLOB,target_branch TEXT,UNIQUE(workspace_id,repo_id)); CREATE TABLE local_participants(id BLOB PRIMARY KEY,username TEXT); CREATE TABLE local_issue_assignees(id BLOB PRIMARY KEY,issue_id BLOB,user_id BLOB,UNIQUE(issue_id,user_id)); CREATE TABLE execution_processes(id BLOB PRIMARY KEY,session_id BLOB,status TEXT DEFAULT 'running',run_reason TEXT DEFAULT 'codingagent',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
